    /// <summary>
/// designed by AVANADE  
/// </summary>
/// <param name = "_quotationId">QuotationIdBase</param>
void KCS_deletePrevVersionMark(QuotationIdBase  _quotationId)
{
    CustQuotationJour           custQuotationJour;

    update_recordset custQuotationJour
    setting KCS_IsLastQuotationVersion = NoYes::No
        where custQuotationJour.KCS_QuotationId == _quotationId
           && custQuotationJour.KCS_IsLastQuotationVersion == NoYes::Yes;
}

/// <summary>
/// Creates letter introduction for electronic report
/// </summary>
/// <returns>str</returns>
public str avaIntroduction()
{
    str avaIntroduction;
    ContactPerson avaContact = ContactPerson::find(this.AVAContactPersonId);
    DirPerson avaPerson = DirPerson::find(avaContact.Party);
    DirPersonName avaPersonName = DirPersonName::find(avaPerson.RecId);

    if(avaPerson.Gender == Gender::Male)
    {
        avaIntroduction = SysLabel::labelId2String(literalStr("@NDX:DearMr"), this.LanguageId) + ' ';

        if(avaPersonName.LastNamePrefix)
        {
            avaIntroduction += avaPersonName.LastNamePrefix + ' ';
        }

        avaIntroduction += avaPersonName.LastName;
    }
    else if(avaPerson.Gender == Gender::Female)
    {
        avaIntroduction = SysLabel::labelId2String(literalStr("@NDX:DearMrs"), this.LanguageId) + ' ';

        if(avaPersonName.LastNamePrefix)
        {
            avaIntroduction += avaPersonName.LastNamePrefix + ' ';
        }

        avaIntroduction += avaPersonName.LastName;
    }

    else    // Gender unkown or unspecified
    {
        avaIntroduction = SysLabel::labelId2String(literalStr("@NDX:DearSirOrMadam"), this.LanguageId);
    }



    return avaIntroduction;
}

