/// <summary>
/// designed by AVANADE KCS_setWeightTotal from AX2009
/// </summary>
/// <param name = "_quotTable">SalesQuotationTable</param>
/// <returns>Weight</returns>
Weight AVAsetWeightTotal(SalesQuotationTable _quotTable)
{
    InventTable         inventTable;
    InventTableModule   inventTableModule;
    Weight              tempWeight, ret;
    SalesQuotationLine  salesQuotationLine;

    while select salesQuotationLine where salesQuotationLine.QuotationId == _quotTable.QuotationId &&
                                      salesQuotationLine.KCS_CRMIsAlternativeLine == NoYes::No
    {
        inventTable       = InventTable::find(salesQuotationLine.ItemId);
        inventTableModule = inventTableModule::find(salesQuotationLine.ItemId, ModuleInventPurchSales::Sales);
        tempWeight = inventTable.NetWeight * inventTableModule.PriceUnit;
        //tempWeight = UnitConvert::valueConvert(tempWeight, unitParameters.unitIdWeight, unitParameters.unitIDKg, salesQuotationLine.ItemId, false);
        tempWeight = EcoResProductUnitConverter::convertForReleasedProduct(salesQuotationLine.ItemId, salesQuotationLine.InventDimId, tempWeight, UnitOfMeasure::findBySymbol('g').RecId, UnitOfMeasure::findBySymbol('kg').RecId, NoYes::No, NoYes::No);

        if(salesQuotationLine.PriceUnit != 0)
        {
            tempWeight = tempWeight * salesQuotationLine.SalesQty / salesQuotationLine.PriceUnit;
        }
        ret += tempWeight;
    }

    return ret;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
void  initFromSalesQuotationTable(SalesQuotationTable  _salesQuotationTable)
{
    next initFromSalesQuotationTable(_salesQuotationTable);

    this.KCS_QuotationId = _salesQuotationTable.QuotationId;

    if (CustQuotationJour::numberOfQuotations(_salesQuotationTable))
    {
        this.KCS_deletePrevVersionMark(_salesQuotationTable.QuotationId);
    }
    this.KCS_IsLastQuotationVersion = NoYes::Yes;

    //this.AVAsetWeightTotal(_salesQuotationTable);
    this.KCS_ShowIntPosPrice        = _salesQuotationTable.KCS_ShowIntPosPrice;
    this.KCS_BOSSpecialPrice        = _salesQuotationTable.KCS_BOSSpecialPrice;
    this.KCS_KBVCommissSalesGroup   = _salesQuotationTable.KCS_CommissSalesGroup;
    this.KCS_BOSCommissCutPct       = _salesQuotationTable.AVACBSCommissCutPct;
    this.AVAContactPersonId         = _salesQuotationTable.ContactPersonId;
    this.AVAEmail                   = _salesQuotationTable.Email;
    this.KCS_KBVBuildingProjectID   = _salesQuotationTable.KCS_KBVBuildingProjectID;
    this.KCS_KBVSubject             = _salesQuotationTable.KCS_KBVSubject;
    this.KCS_KBVRequestId           = _salesQuotationTable.KCS_KBVRequestId;
    this.AVAQuotationExpiryDate     = _salesQuotationTable.QuotationExpiryDate;
    this.AVASalesUnitId             = _salesQuotationTable.SalesUnitId;
    this.AVANoExpiryOverrun         = _salesQuotationTable.AVANoExpiryOverrun;
    this.AVAPriceDate               = _salesQuotationTable.KCS_PriceDate;
}

/// <summary>
///    AVA <c>avaPreviousCustQuotationJour</c> method.
/// </summary>
/// <returns>
///    <c>CustQuotationJour</c> as return value
/// </returns>
public CustQuotationJour avaPreviousCustQuotationJour()
{
    CustQuotationJour       retval;

    CustQuotationSalesLink  locCustQuotationSalesLink;
    CustQuotationSalesLink  locCustQuotationSalesLinkPrevious;

    select firstonly locCustQuotationSalesLink
    order by locCustQuotationSalesLink.quotationDate desc, RecId desc
    where   locCustQuotationSalesLink.quotationId   == this.QuotationId
        &&  locCustQuotationSalesLink.quotationDate == this.QuotationDate
        &&  locCustQuotationSalesLink.salesId       == this.SalesId;

    if(locCustQuotationSalesLink.RecId)
    {
        select firstonly locCustQuotationSalesLinkPrevious
        order by locCustQuotationSalesLinkPrevious.quotationDate desc, RecId desc
        where   locCustQuotationSalesLinkPrevious.OrigQuotationId   == locCustQuotationSalesLink.OrigQuotationId
            &&  locCustQuotationSalesLinkPrevious.quotationDate     <= locCustQuotationSalesLink.quotationDate
            &&  locCustQuotationSalesLinkPrevious.RecId             != locCustQuotationSalesLink.RecId;

        if(locCustQuotationSalesLinkPrevious.RecId)
        {
            select firstonly retval
            order by quotationDate desc, RecId desc
            where   retval.QuotationId   == locCustQuotationSalesLinkPrevious.quotationId
                &&  retval.QuotationDate == locCustQuotationSalesLinkPrevious.quotationDate
                &&  retval.SalesId       == locCustQuotationSalesLinkPrevious.salesId;
        }
    }     

    return retval;
}

/// <summary>
/// Gets first CustQuotationJour for this QuotationId
/// </summary>
/// <returns>CustQuotationJour</returns>
public CustQuotationJour avaFirstQuotation()
{
    CustQuotationSalesLink  avaCustQuotationSalesLink;
    CustQuotationJour       avaCustQuotationJour;
    SalesQuotationTable     avaSalesQuotationTable = this.salesQuotationTable();

    select firstonly avaCustQuotationSalesLink
        order by QuotationDate asc, QuotationId asc
        where avaCustQuotationSalesLink.OrigQuotationId == avaSalesQuotationTable.QuotationId
    join avaCustQuotationJour
        where avaCustQuotationJour.QuotationId   == avaCustQuotationSalesLink.QuotationId   &&
                avaCustQuotationJour.QuotationDate        == avaCustQuotationSalesLink.QuotationDate &&
                avaCustQuotationJour.QuotationType        == QuotationType::Sales;

    return avaCustQuotationJour;
}

/// <summary>
/// returns information of all inquirers associated with this requestId
/// </summary>
/// <returns>str</returns>
public str avaGetInquirerRequestInfo()
{
    str avaRequestInfo;
    KCS_KBVInquirerOfTheRequest avaInquirerOfRequest;

    if(!this.KCS_KBVRequestId)
    {
        return avaRequestInfo;
    }

    while select avaInquirerOfRequest
        where avaInquirerOfRequest.KCS_KBVRequestID == this.KCS_KBVRequestId
        && avaInquirerOfRequest.KCS_KBVPublishIotR == NoYes::Yes
    {
        if(avaRequestInfo != '')
        {
            avaRequestInfo += '\n';
        }

        avaRequestInfo += avaInquirerOfRequest.avaGetInquirerInfo(this.LanguageId);
    }

    return avaRequestInfo;
}

/// <summary>
/// returns if current KCS_SendMode is Proforma or not
/// </summary>
/// <returns>boolean</returns>
public boolean avaIsProforma()
{
    return this.KCS_SendMode == KCS_SendMode::Proforma;
}

/// <summary>
/// returns the latest CustQuotationJour record for a provided _quotationId
/// </summary>
/// <param name = "_quotationId">QuotationId</param>
/// <returns>CustQuotationJour</returns>
public static CustQuotationJour avaFindLatestQuotation(QuotationId _quotationId)
{
    CustQuotationSalesLink    avCustQuotationSalesLink;
    CustQuotationJour         avaCustQuotationJour;

    select firstonly TableId from avCustQuotationSalesLink
            order by QuotationDate desc, QuotationId desc
            where avCustQuotationSalesLink.OrigQuotationId == _quotationId
        join avaCustQuotationJour
            where avaCustQuotationJour.QuotationId == avCustQuotationSalesLink.QuotationId   &&
                  avaCustQuotationJour.QuotationDate   == avCustQuotationSalesLink.QuotationDate;

    return avaCustQuotationJour;
}

