/// <summary>
///    AVA <c>displayAVABaseAmount</c> method.
/// </summary>
/// <returns>
///    <c>Amount</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Amount displayAVABaseAmount(boolean _rounded = true)
{
    Amount              retVal;

    CustQuotationTrans  locCustQuotationTrans;

    select sum(KCS_QLLVAmount)
    from    locCustQuotationTrans
    where   locCustQuotationTrans.QuotationId               == this.QuotationId
        &&  locCustQuotationTrans.QuotationDate             == this.QuotationDate
        &&  locCustQuotationTrans.SalesId                   == this.SalesId
        &&  locCustQuotationTrans.KCS_CRMIsAlternativeLine  == NoYes::No
        &&  locCustQuotationTrans.KCS_QLInternalPosition    == 1;

    retVal = locCustQuotationTrans.KCS_QLLVAmount;

    select sum(LineAmount)
    from    locCustQuotationTrans
    where   locCustQuotationTrans.QuotationId               == this.QuotationId
        &&  locCustQuotationTrans.QuotationDate             == this.QuotationDate
        &&  locCustQuotationTrans.SalesId                   == this.SalesId
        &&  locCustQuotationTrans.KCS_CRMIsAlternativeLine  == NoYes::No
        &&  locCustQuotationTrans.KCS_QLInternalPosition    == 0;

    retVal += locCustQuotationTrans.LineAmount;

    if(_rounded)
    {
        retVal = decround(retVal, 2);
    }

    return retVal;
}

/// <summary>
///    AVA <c>displayAVASpecialDiscAmount</c> method.
/// </summary>
/// <param name="_calculate">
///     <c>boolean</c> as type
/// </param>
/// <param name="_discountNo">
///     <c>int</c> as type, 0 for all
/// </param>
/// <param name="_updateOnCalculate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>Amount</c> as return value
/// </returns>
public Amount avaSpecialDiscAmount( boolean _calculate          = false,
                                    int     _discountNo         = 0,     
                                    boolean _updateOnCalculate  = false )
{
    Amount                      retVal;
    int                         locDiscountNo;
    Amount                      locTmpAmount;
    Amount                      locTmpAmount1;
    Amount                      locTmpAmount2;
    Amount                      locTmpAmount3;
    Amount                      locBaseAmount;
    AVASpecialDiscQuotationJour locAVASpecialDiscQuotationJour;

    locAVASpecialDiscQuotationJour = AVASpecialDiscQuotationJour::findQuotation(this.RecId);

    locDiscountNo = _discountNo;
    if(     locDiscountNo < 0
        &&  locDiscountNo > 3)
    {
        locDiscountNo = 0;
    }

    if(locAVASpecialDiscQuotationJour.RecId)
    {
        if(_calculate)
        {
            locBaseAmount   = this.displayAVABaseAmount();
            locTmpAmount    = locBaseAmount;

            locTmpAmount1   = decround((locTmpAmount * locAVASpecialDiscQuotationJour.SpecialDiscountPct1 / 100), 2);
            locTmpAmount    = locTmpAmount - locTmpAmount1;
            locTmpAmount2   = decround((locTmpAmount * locAVASpecialDiscQuotationJour.SpecialDiscountPct2 / 100), 2);
            locTmpAmount    = locTmpAmount - locTmpAmount2;
            locTmpAmount3   = decround((locTmpAmount * locAVASpecialDiscQuotationJour.SpecialDiscountPct3 / 100), 2);
            locTmpAmount    = locTmpAmount - locTmpAmount3;

            if(locDiscountNo == 0)
            {
                retVal      = locTmpAmount1 + locTmpAmount2 + locTmpAmount3;
            }
            if(locDiscountNo == 1)
            {
                retVal      = locTmpAmount1;
            }
            else if(locDiscountNo == 2)
            {
                retVal      = locTmpAmount2;
            }
            else if(locDiscountNo == 3)
            {
                retVal      = locTmpAmount3;
            }

            if(_updateOnCalculate)
            {
                ttsbegin;
                locAVASpecialDiscQuotationJour.selectForUpdate(true);
                locAVASpecialDiscQuotationJour.SpecialDiscountAmount1 = locTmpAmount1;
                locAVASpecialDiscQuotationJour.SpecialDiscountAmount2 = locTmpAmount2;
                locAVASpecialDiscQuotationJour.SpecialDiscountAmount3 = locTmpAmount3;
                locAVASpecialDiscQuotationJour.update();
                ttscommit;
            }
        }
        else
        {
            if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount1   != 0
                ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct1      != 0    )
            {
                retVal += locAVASpecialDiscQuotationJour.SpecialDiscountAmount1;
            }
            if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount2   != 0
                ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct2      != 0    )
            {
                retVal += locAVASpecialDiscQuotationJour.SpecialDiscountAmount2;
            }
            if(     locAVASpecialDiscQuotationJour.SpecialDiscountAmount3   != 0
                ||  locAVASpecialDiscQuotationJour.SpecialDiscountPct3      != 0    )
            {
                retVal += locAVASpecialDiscQuotationJour.SpecialDiscountAmount3;
            }
        }
    }
    else
    {
        retVal = 0.0;
    }

    return retVal;
}

